create view public.exam_analytics with (security_invoker=true) as select tenant_id,exam_session_id,count(*) as student_count,avg(score) as average_score,min(score) as minimum_score,max(score) as maximum_score from public.exam_results where status in('GRADED','PUBLISHED') group by tenant_id,exam_session_id;revoke all on public.exam_analytics from anon,authenticated;insert into public.permissions(code,name,description) values('exam_analytics.read','Read exam analytics','View exam performance analytics') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code='exam_analytics.read' on conflict do nothing;
